sys_ux_data_broker_transform.props:
{
  "type": "object",
  "properties": {
    "completeFields": {
      "type": "object",
      "description": "An object containing metadata for all fields on the form, where each key is a field name and the value is its metadata.",
      "additionalProperties": {
        "type": "object",
        "properties": {
          "label": { "type": "string", "description": "The display label of the field." },
          "type": { "type": "string", "description": "The data type of the field (e.g., string, choice, number)." },
          "mandatory": { "type": "boolean", "description": "Indicates if the field is mandatory." },
          "readonly": { "type": "boolean", "description": "Indicates if the field is read-only." }
        },
        "required": ["label", "type"]
      }
    },
    "needFields": {
      "type": "string",
      "description": "A comma-separated string of field names that are required to be filtered from the completeFields."
    }
  },
  "required": ["completeFields", "needFields"]
}

sys_ux_data_broker_transform.script:
function transform(input) {
    var completeFields = input.completeFields; // Object with field names as keys
    var neededFields = input.needFields.split(','); // Array of required field names

    // Filter the fields to include only those needed
    var filteredFields = {};
    neededFields.forEach(fieldName => {
        if (completeFields[fieldName]) { // Check if the field exists in completeFields
            filteredFields[fieldName] = completeFields[fieldName];
        }
    });

    return filteredFields; // Return or process the filtered fields
}
